31	pub(crate) fn render_tab_bar(
32	    tabs: &[SelectionTab],
33	    active_idx: usize,
34	    area: Rect,
35	    buf: &mut Buffer,
36	) {
37	    for (offset, line) in tab_bar_lines(tabs, active_idx, area.width)
38	        .into_iter()
39	        .take(area.height as usize)
40	        .enumerate()
41	    {
42	        line.render(
