54	fn tab_bar_lines(tabs: &[SelectionTab], active_idx: usize, width: u16) -> Vec<Line<'static>> {
55	    if tabs.is_empty() {
56	        return Vec::new();
57	    }
58	
59	    let max_width = width.max(1) as usize;
60	    let mut lines = Vec::new();
61	    let mut current_spans: Vec<Span<'static>> = Vec::new();
62	    let mut current_width = 0usize;
63	
64	    for (idx, tab) in tabs.iter().enumerate() {
65	        let unit = tab_unit(tab.label.as_str(), idx == active_idx);
66	        let unit_width = Line::from(unit.clone()).width();
67	        let gap_width = if current_spans.is_empty() {
68	            0
69	        } else {
70	            TAB_GAP_WIDTH
71	        };
72	
73	        if !current_spans.is_empty() && current_width + gap_width + unit_width > max_width {
74	            lines.push(Line::from(current_spans));
75	            current_spans = Vec::new();
76	            current_width = 0;
77	        }
78	
79	        if !current_spans.is_empty() {
80	            current_spans.push("  ".into());
81	            current_width += TAB_GAP_WIDTH;
82	        }
83	        current_width += unit_width;
84	        current_spans.extend(unit);
85	    }
86	
87	    if !current_spans.is_empty() {
88	        lines.push(Line::from(current_spans));
89	    }
90	    lines
91	}
